def health() -> dict:
    """Return simple health status payload.

    Frameworks can import and expose this via an HTTP route.
    """
    return {"status": "ok"}

import pytest

from core.health import health


def test_health_returns_dict():
    result = health()
    assert isinstance(result, dict)


def test_health_status_ok():
    result = health()
    assert result == {"status": "ok"}


def test_health_has_only_expected_keys():
    result = health()
    assert set(result.keys()) == {"status"}
